#!/usr/bin/env python3
"""Render survey reports from recorded machine-readable evidence."""
import collections,json,pathlib,subprocess,sys
from stage0_upstream import ROOT,OUT

def read(name):return json.loads((OUT/name).read_text())
def write(name,lines):(OUT/name).write_text('\n'.join(lines)+'\n')
def build_report():
 rs=read('build-at-t.json');lines=['# Build and test at t','','All numbers: from `docker/`, `docker compose run --rm ktester bash -c \'python /work/docker/stage0_build_tests.py\'`, followed by `docker compose run --rm ktester bash -c \'python /work/docker/stage0_build_tests.py --repeat-existing\'`. Render with `python3 docker/stage0_reports.py build`. Commands, environment, wall times and counts are in build-at-t.json and build/<project>.json; complete stdout/stderr logs are in build/*.txt.','','Fresh `git archive` exports were built under scratch/build. Shared Maven cache: compose volume ktester-m2 mounted at /root/.m2. Zero Surefire XML files means no executed-test evidence, not an empty suite. Two projects ran concurrently; wall times include contention. Each project was capped at a combined 30 minutes, with each test command limited to remaining time. The four successful projects were tested again; two passes cannot establish absence of flakiness.','','| Project | Package exit / seconds | Test exit / seconds | Tests / failures / errors / skipped | XML files | Repeat exit / seconds / same counts |','|---|---|---|---|---:|---|']
 for r in rs:
  a,b=r['runs'];c=r['counts'];rep=r.get('repeat');repeat=f"{rep['exit_code']} / {rep['seconds']} / {rep['same_counts_as_first']}" if rep else 'not attempted after repeated Maven failure'
  lines.append(f"| {r['project']} | {a['exit_code']} / {a['seconds']} | {b['exit_code']} / {b['seconds']} | {c['tests']} / {c['failures']} / {c['errors']} / {c['skipped']} | {r['surefire_xml_files']} | {repeat} |")
 lines+=['','## Build configuration and loop implications','','Environment (recorded by driver): OpenJDK 17.0.20.1 and Maven 3.9.9. No compiler-release overrides or extra toolchains were needed for successful builds. Exact package command: `mvn -q -DskipTests -Drat.skip -Dcheckstyle.skip -Dspotbugs.skip -Dpmd.skip -Dmaven.javadoc.skip package`; exact test command: `mvn -q test`. Skip properties are harmless where undeclared; plain test commands use normal lifecycle bindings.','', 'POM/build inspection: `rg -n "source>|target>|release>|jdkToolchain|artifactId>|phase>|sourceDirectory>|testSourceDirectory>|target name=" scratch/at-t/{commons-codec,commons-collections,gson,ruler}/pom.xml scratch/at-t/jdom2/build.xml`.','', '- commons-codec and commons-collections target Java 8 and build on the installed JDK. Their parent-driven quality/coverage plugins and collections test-resource generation should be retained or deliberately controlled during later loops.','- Gson sets release 7 and accepts a compiler toolchain version [11,); the installed JDK satisfies it. Its reactor includes extras and a ProGuard build/test module. The recorded suite total covers all reactor Surefire reports, not only gson/src/test/java.','- Ruler targets Java 8 and explicitly sets sourceDirectory=src/main and testSourceDirectory=src/test. Checkstyle and SpotBugs are configured in its POM; seeded randomized tests print reproduction seeds in the retained logs.','- JDOM upstream is an Ant project with build.xml and Maven publishing templates under maven/, not a root Maven project. Both package and test fail with MissingProjectException because pom.xml is absent. This is not evidence of JDK incompatibility. Per the repeated-failure rule, no third Maven attempt or transplanted snapshot POM was used. An Ant-specific experiment setup remains open.','- Initial builds may populate the shared dependency/plugin cache. Quiet logs do not prove which artifacts were newly downloaded. Successful repeat test runs reuse the same cache.']
 for r in rs:
  if not r['surefire_xml_files']:continue
  lines.append(f"- {r['project']}: {len(r['slow_testcases'])} individual tests and {len(r['slow_suites'])} suites exceeded 60 seconds in the first run (Surefire XML, same driver invocation).")
 write('build-at-t.md',lines)

def extractor_report():
 r=read('extractor-check.json');a=json.loads((ROOT/'data/project_index/json/commons-cli.json').read_text());b=json.loads((ROOT/'scratch/extract-check/project_index/json/commons-cli.json').read_text())
 lines=['# Commons CLI extractor check','','Verdict: partial rebuild only. JSON, control-flow and calling-graph artifacts and a Lucene index were produced; invoke-pattern extraction fails reproducibly with NetworkXNoPath. No pipeline source was patched.','','Invocation for all measurements: from docker/, `docker compose run --rm ktester bash -c \'python /work/docker/stage0_build_index.py > /work/results/stage0-survey/extractor-run.txt 2>&1\'`. Report rendering and supplementary counts: `python3 docker/stage0_reports.py extractor`. The first failed run is preserved in extractor-first-failure.txt. The second run catches the same invoke failure only to complete independent indexing/comparison; no third attempt was made. Full errors are retained in extractor-check.json and both logs.','',f"Measured second-run extraction/index wall time: {r['seconds']} seconds (comparison time excluded).",'', '## Inputs and settings established by source inspection','','Read: code/Java/project-info-process/src/PreProcessor.java, code/procedure/preprocess_project.py, code/preparation.py, the FileStructure configuration in code/settings.py, CodeInfoExtractor.java, and IndexBuilder.java. Only the two packaged Java jars and procedure.preprocess_project are loaded by the driver; no LLM module or settings object is instantiated.','', '- Fresh upstream commons-cli at 90b3f2e is exported into scratch/extract-check/projects/commons-cli. Snapshot libs/, dependencies.txt, and src/test-original/ are copied there. dataset_info.json initially contains the unchanged commons-cli entry.','- PreProcessor enumerates its input directory as projects and reads each project’s src/main/java, src/test-original/java, and libs/*.jar. It appends json/ and codegraph/ to its output root. Thus the driver passes projects/ and project_index/, correcting the stale path wiring shown in preparation.py, without editing it.','- The Python graph stages need only DATASET_PATH (containing dataset_info.json) and CODE_INFO_PATH (containing json/ and codegraph/). A SimpleNamespace provides those attributes. dependencies.txt is copied for compatibility but is not read by these stages.','- IndexBuilder receives group, project_index/json, project_index/lucene. Its code indexes production methods under source, not test methods. Indexed identifiers below are class_fqn#signature.','- Library inputs lack the JUnit 4 Assert class referenced by test-original sources; the extractor logs unresolved org.junit.Assert symbols. That warning is distinct from the fatal graph reachability error.','','## Normalized comparisons','','JSON comparison sorts object keys and normalizes CRLF to LF; it preserves list order and Windows/Linux path separators so those differences remain visible.','', '| Artifact | Author / generated top-level entries | Differing JSON leaf paths |','|---|---|---:|']
 for k,v in r['json'].items():lines.append(f"| {k} | {v.get('author_top_level_entries','')} / {v.get('generated_top_level_entries','')} | {v.get('differing_paths_count',v.get('error'))} |")
 lines+=['','Structure detail (same report invocation):']
 for key in ['source','test','import_dict']:lines.append(f"- {key}: author {len(a[key])}, generated {len(b[key])} entries.")
 paths=r['json']['json/commons-cli.json']['differing_paths'];groups=collections.Counter(x.split('/')[1] for x in paths)
 lines.append('- Project JSON differences by root key: '+', '.join(f'{k}={v}' for k,v in sorted(groups.items()))+'.')
 for artifact in ['codegraph/commons-cli_callgraph.json','codegraph/commons-cli_controlflow.json']:
  fields=collections.Counter(p.split('/')[-1] for p in r['json'][artifact]['differing_paths']);lines.append('- '+artifact+' differing final path components: '+str(dict(sorted(fields.items())))+'.')
 test_ids=lambda x:{c+'#'+m['signature'] for c,v in x['test'].items() for ms in v['methods'].values() for m in ms}
 ai,bi=test_ids(a),test_ids(b);lu=r['lucene'];lines += [f"- Test identifiers from project JSON: author {len(ai)}, generated {len(bi)}, author-only {len(ai-bi)}, generated-only {len(bi-ai)}. This is separate from the production-method Lucene index.",f"- Lucene document counts: author {lu['authors']['document_count']}, generated {lu['generated']['document_count']}; full identifier sets equal: {lu['identifiers_equal']}.",'','Differences include Windows versus Unix relative file paths, a much larger author import dictionary, caller ordering, and control-flow node identifiers. Counts do not establish semantic graph differences: raw node IDs/list order were deliberately not relabeled. Full differing paths and Lucene identifier sets are preserved in extractor-check.json.','','## Fatal error and missing-input diagnosis','','```text',r['errors'][0].strip(),'```','','No missing file is identified by the fatal exception: a control-flow target is unreachable from the chosen source node. All required project inputs exist. The absent JUnit Assert dependency is a separate warning; adding it has not been tested and is not claimed to fix graph reachability. The full invoke-pattern rebuild remains unresolved.']
 write('extractor-check.md',lines)

def dataset_report():
 r=read('dataset-prepare-check.json');lines=['# DatasetPrepare round trip and population extension','','Verdict: successful for the existing commons-cli methods and for an additional public Options method. No generated tests or LLM calls were involved.','','All measured values: from docker/, `docker compose run --rm ktester bash -c \'python /work/docker/stage0_dataset_prepare.py > /work/results/stage0-survey/dataset-prepare-run.txt 2>&1\'`. Render with `python3 docker/stage0_reports.py dataset`. Full field comparisons: dataset-prepare-check.json; generated entries: dataset-prepare-existing.json and dataset-prepare-enlarged.json.','','## Exact metadata contract','','Source read in full: code/Java/project-info-process/src/DatasetPrepare.java; overload matching checked in extractor/SpoonExtractor.java. The expected JSON is an array of objects:', '', '```json',json.dumps([{'project_name':'commons-cli','put_path':'/root/experiments/puts/commons-cli','method_name_to_idx':{'org.apache.commons.cli.HelpFormatter.renderOptions(StringBuffer, int, Options, int, int)':0,'org.apache.commons.cli.PatternOptionBuilder.getValueType(char)':1}}],indent=2),'```','','Every consumed field is shown. The input field is **put_path**, not project_url. Its literal /root/experiments/puts/ prefix is removed; the resulting string becomes output project-url and is resolved relative to the dataset directory. It is a local source path, not a GitHub URL, and nothing is cloned by DatasetPrepare. The scratch commons-cli symlink points to projects/commons-cli so the original project-url value is retained.','', 'method_name_to_idx is an object mapping full method signatures to arbitrary JSON values; only keys are read, and numeric values are ignored. The class is identified by fully qualified name and the method by name plus ordered argument types. Parameters must be comma-space separated. Generic type arguments are removed. Matching requires equal arity and checks whether each Spoon qualified type ends with the supplied type after periods are changed to dollar signs; simple type names work, fully qualified parameter types may therefore fail. No-argument methods use (). Constructors are not selected. Private methods are rejected.','', 'The generated test ID uses the simple class name plus method name; overloads receive numeric suffixes. The source updates the suffixed key rather than the base counter on collision, so repeated overloads beyond the first collision may reuse an ID. Avoid assuming arbitrary overloaded populations are safe without an additional check. Missing/unresolved methods may yield empty bodies instead of aborting; this check validates nonempty bodies.','', 'The extractor reads src/main/java and libs under the resolved local project, uses Spoon at Java compliance level 11, and writes dataset_info.json. It does not read test sources; test-class and test-path are synthesized naming conventions, not tests it found or generated.','','## Existing entry comparison','',f"Original methods: {r['original_count']}; regenerated methods: {r['generated_count']}; enlarged population: {r['enlarged_count']}; combined driver wall time: {r['seconds']} seconds.",'', '| Existing method | focal-method | class-code | test-class | test-path | source-path |','|---|---|---|---|---|---|']
 for k,v in r['fields'].items():lines.append('| '+k+' | '+' | '.join(v[f]['comparison'] for f in ['focal-method','class-code','test-class','test-path','source-path'])+' |')
 lines+=['','All other method identity fields and both project fields match exactly (same driver invocation). Differences in focal-method and class-code are CRLF versus LF only, not source content changes.','','## Additional method','']
 for x in r['added_methods']:lines.append(f"- {x['id']}: {x['method']}; focal body nonempty={x['nonempty_focal_method']}; class context nonempty={x['nonempty_class_code']}.")
 lines+=['','scratch/extract-check/dataset_meta.json and dataset_info.json retain the enlarged population. The committed existing-entry result preserves the earlier round trip.']
 write('dataset-prepare-check.md',lines)

if __name__=='__main__':
 {'build':build_report,'extractor':extractor_report,'dataset':dataset_report}[sys.argv[1]]()
